/* cppi::0468009adaee7a82d57b054440682765ba4bb10f7fe080e699b34c83234fd2b1 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-22' and end_date = '2025-04-22')
and start_date = '2025-04-22' and end_date = '2025-04-22'

